import math
import re
from typing import Optional

class Token:
    def __init__(self, type: str, value: any, pos: int):
        self.type = type
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type}, {self.value!r}, pos={self.pos})"

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.tokens: list[Token] = []
        self.tokenize()

    def tokenize(self):
        text = self.text
        n = len(text)
        pos = 0
        while pos < n:
            # Skip whitespace
            if text[pos].isspace():
                pos += 1
                continue

            # Check for two-character operators first
            if pos + 1 < n:
                two = text[pos:pos+2]
                if two in ('==', '!=', '<=', '>=', '&&', '||'):
                    self.tokens.append(Token(two, two, pos))
                    pos += 2
                    continue

            # Single character operators
            ch = text[pos]
            if ch in ('+', '-', '*', '/', '%', '^', '!', '?', ':', '(', ')', '<', '>'):
                self.tokens.append(Token(ch, ch, pos))
                pos += 1
                continue

            # Number literals
            if ch.isdigit() or (ch == '.' and pos + 1 < n and text[pos+1].isdigit()):
                start = pos
                has_dot = False
                pos += 1
                while pos < n and (text[pos].isdigit() or (text[pos] == '.' and not has_dot)):
                    if text[pos] == '.':
                        has_dot = True
                    pos += 1
                num_str = text[start:pos]
                if has_dot:
                    val = float(num_str)
                else:
                    val = int(num_str)
                self.tokens.append(Token('NUMBER', val, start))
                continue

            # Identifiers and keywords
            if ch.isalpha() or ch == '_':
                start = pos
                pos += 1
                while pos < n and (text[pos].isalnum() or text[pos] == '_'):
                    pos += 1
                name = text[start:pos]
                self.tokens.append(Token('IDENT', name, start))
                continue

            # Unknown character
            raise SyntaxError(f"Unexpected character '{ch}' at position {pos}")

        # Add end marker
        self.tokens.append(Token('EOF', None, pos))

class Parser:
    def __init__(self, tokens: list[Token], env: dict[str, float] | None):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def current(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset: int = 0) -> Token:
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return Token('EOF', None, -1)

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, type: str, value: any = None) -> Token:
        tok = self.current()
        if tok.type != type or (value is not None and tok.value != value):
            raise SyntaxError(f"Expected {type} {value!r}, got {tok.type} {tok.value!r} at position {tok.pos}")
        return self.advance()

    def parse(self) -> int | float:
        result = self.parse_ternary()
        # Check for trailing tokens
        if self.current().type != 'EOF':
            raise SyntaxError(f"Unexpected token {self.current().type} {self.current().value!r} at position {self.current().pos}")
        return result

    def parse_ternary(self) -> int | float:
        """Parse conditional expression: a ? b : c (right-associative)"""
        cond = self.parse_or()
        if self.current().type == '?':
            self.advance()
            true_expr = self.parse_ternary()  # right-associative
            self.expect(':')
            false_expr = self.parse_ternary()  # right-associative
            if cond != 0:
                return true_expr
            else:
                return false_expr
        return cond

    def parse_or(self) -> int | float:
        """Parse || and && with short-circuit evaluation"""
        left = self.parse_and()
        while self.current().type == '||':
            self.advance()
            # Short-circuit: if left is non-zero, skip right
            if left != 0:
                # Need to parse right but don't evaluate it
                self.parse_and()
                left = 1
            else:
                right = self.parse_and()
                left = 1 if right != 0 else 0
        return left

    def parse_and(self) -> int | float:
        """Parse && with short-circuit evaluation"""
        left = self.parse_comparison()
        while self.current().type == '&&':
            self.advance()
            # Short-circuit: if left is zero, skip right
            if left == 0:
                self.parse_comparison()
                left = 0
            else:
                right = self.parse_comparison()
                left = 1 if right != 0 else 0
        return left

    def parse_comparison(self) -> int | float:
        """Parse comparison operators (non-associative)"""
        left = self.parse_addition()
        if self.current().type in ('==', '!=', '<', '<=', '>', '>='):
            op = self.advance().value
            right = self.parse_addition()
            if op == '==':
                return 1 if left == right else 0
            elif op == '!=':
                return 1 if left != right else 0
            elif op == '<':
                return 1 if left < right else 0
            elif op == '<=':
                return 1 if left <= right else 0
            elif op == '>':
                return 1 if left > right else 0
            elif op == '>=':
                return 1 if left >= right else 0
        return left

    def parse_addition(self) -> int | float:
        """Parse + and - (left-associative)"""
        left = self.parse_multiplication()
        while self.current().type in ('+', '-'):
            op = self.advance().value
            right = self.parse_multiplication()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_multiplication(self) -> int | float:
        """Parse *, /, % (left-associative)"""
        left = self.parse_unary()
        while self.current().type in ('*', '/', '%'):
            op = self.advance().value
            right = self.parse_unary()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # If both are ints and division is exact, return int
                if isinstance(left, int) and isinstance(right, int):
                    if left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                else:
                    left = left / right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                left = left % right
        return left

    def parse_unary(self) -> int | float:
        """Parse unary operators: -, +, !"""
        if self.current().type == '-':
            self.advance()
            operand = self.parse_unary()
            return -operand
        elif self.current().type == '+':
            self.advance()
            operand = self.parse_unary()
            return operand
        elif self.current().type == '!':
            self.advance()
            operand = self.parse_unary()
            return 1 if operand == 0 else 0
        return self.parse_power()

    def parse_power(self) -> int | float:
        """Parse power operator ^ (right-associative)"""
        base = self.parse_atom()
        if self.current().type == '^':
            self.advance()
            exponent = self.parse_power()  # right-associative
            return base ** exponent
        return base

    def parse_atom(self) -> int | float:
        """Parse atoms: numbers, identifiers, function calls, parentheses"""
        tok = self.current()

        if tok.type == 'NUMBER':
            self.advance()
            return tok.value

        if tok.type == 'IDENT':
            name = tok.value
            self.advance()
            # Check for function call
            if self.current().type == '(':
                return self.parse_function_call(name)
            # Otherwise it's a variable lookup
            if name not in self.env:
                raise NameError(f"Unknown variable '{name}'")
            return self.env[name]

        if tok.type == '(':
            self.advance()
            result = self.parse_ternary()
            self.expect(')')
            return result

        # Check for lone operators that shouldn't appear here
        if tok.type in ('=', '&', '|'):
            raise SyntaxError(f"Unexpected token {tok.type} {tok.value!r} at position {tok.pos}")

        raise SyntaxError(f"Unexpected token {tok.type} {tok.value!r} at position {tok.pos}")

    def parse_function_call(self, name: str) -> int | float:
        """Parse function calls: min(...), max(...), abs(...)"""
        self.expect('(')

        if name == 'abs':
            # abs takes exactly 1 argument
            arg = self.parse_ternary()
            self.expect(')')
            return abs(arg)

        if name == 'min':
            # min takes 1 or more arguments
            args = []
            args.append(self.parse_ternary())
            while self.current().type == ',':
                self.advance()
                args.append(self.parse_ternary())
            self.expect(')')
            if len(args) == 0:
                raise SyntaxError("min() requires at least one argument")
            return min(args)

        if name == 'max':
            # max takes 1 or more arguments
            args = []
            args.append(self.parse_ternary())
            while self.current().type == ',':
                self.advance()
                args.append(self.parse_ternary())
            self.expect(')')
            if len(args) == 0:
                raise SyntaxError("max() requires at least one argument")
            return max(args)

        raise NameError(f"Unknown function '{name}'")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """
    Evaluate a small expression language.

    Grammar precedence (lowest to highest):
    1. Conditional: a ? b : c (right-associative)
    2. Logical OR: || (short-circuit)
    3. Logical AND: && (short-circuit)
    4. Comparisons: == != < <= > >= (non-associative)
    5. Addition: + - (left-associative)
    6. Multiplication: * / % (left-associative)
    7. Unary: - + ! 
    8. Power: ^ (right-associative)
    9. Atoms: literals, identifiers, function calls, parentheses
    """
    if not expr or not expr.strip():
        raise SyntaxError("Empty input")

    lexer = Lexer(expr)
    parser = Parser(lexer.tokens, env)
    return parser.parse()
