import re
from typing import List, Optional, Tuple, Union


class Version:
    """Represents a SemVer 2.0.0 version."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[List[str]] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease if prerelease is not None else []
        self.build = build

    @classmethod
    def parse(cls, v: str) -> 'Version':
        """Parse a SemVer string into a Version object."""
        if not isinstance(v, str):
            raise ValueError(f"Invalid version: {v}")

        # Strip leading 'v' or '='
        s = v.strip()
        if s.startswith('v') or s.startswith('V'):
            s = s[1:]
        if s.startswith('='):
            s = s[1:]
        s = s.strip()

        if not s:
            raise ValueError(f"Invalid version: {v}")

        # SemVer regex
        # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        # No leading zeros in numeric parts
        # Prerelease identifiers: [0-9A-Za-z-]+, non-empty
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version: {v}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease_str = match.group(4)
        build_str = match.group(5)

        prerelease = None
        if prerelease_str is not None:
            prerelease = prerelease_str.split('.')

        build = build_str

        return cls(major, minor, patch, prerelease, build)

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(self.prerelease)
        if self.build:
            s += "+" + self.build
        return f"Version({s})"

    def __str__(self):
        return self.__repr__()

    def _cmp_key(self) -> Tuple[int, int, int, Union[Tuple[int, ...], Tuple[str, ...]]]:
        """
        Return a comparison key for SemVer precedence.
        Build metadata is ignored.
        Prerelease < release.
        Prerelease identifiers compared numerically when both numeric, numeric < alphanumeric, ASCII order otherwise.
        A shorter prefix list is smaller.
        """
        # For comparison, we need to handle prerelease specially
        if self.prerelease:
            # Convert prerelease identifiers: numeric strings become integers for proper comparison
            # But we need a key that allows proper ordering
            # Each identifier: if it's all digits, it's numeric; otherwise alphanumeric
            # Numeric identifiers are compared as integers
            # Alphanumeric identifiers are compared as strings
            # Numeric < Alphanumeric
            # We'll create a tuple where each element is (0, int_val) for numeric or (1, str_val) for alphanumeric
            key = []
            for ident in self.prerelease:
                if ident.isdigit():
                    key.append((0, int(ident)))
                else:
                    key.append((1, ident))
            return (self.major, self.minor, self.patch, 0, tuple(key))
        else:
            # Release version has no prerelease, so it's greater than any prerelease of the same major.minor.patch
            return (self.major, self.minor, self.patch, 1, ())

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() == other._cmp_key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() < other._cmp_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() <= other._cmp_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() > other._cmp_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() >= other._cmp_key()

    def __ne__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() != other._cmp_key()

    def __hash__(self):
        return hash(self._cmp_key())


def _parse_partial_version(s: str) -> Version:
    """
    Parse a partial version string like '1', '1.2', '1.2.3', '1.x', '1.2.*', 'X'.
    Returns a Version object with missing parts filled with 0.
    """
    s = s.strip()
    if not s:
        raise ValueError("Empty version string")

    # Replace x, X, * with 0
    s = re.sub(r'[xX*]', '0', s)

    # Now parse as normal version
    return Version.parse(s)


def _expand_range(version_str: str) -> Tuple[Version, Version]:
    """
    Expand a version string that might be a partial version or have operators into a range (min, max).
    Returns (min_version, max_version) inclusive.
    """
    s = version_str.strip()
    if not s:
        raise ValueError("Empty version string")

    # Check for operators
    op = None
    ver_str = s
    if s.startswith('>='):
        op = '>='
        ver_str = s[2:].strip()
    elif s.startswith('<='):
        op = '<='
        ver_str = s[2:].strip()
    elif s.startswith('>'):
        op = '>'
        ver_str = s[1:].strip()
    elif s.startswith('<'):
        op = '<'
        ver_str = s[1:].strip()
    elif s.startswith('='):
        op = '='
        ver_str = s[1:].strip()
    else:
        op = '='

    if not ver_str:
        raise ValueError(f"Invalid version string: {version_str}")

    # Parse the version part
    ver = _parse_partial_version(ver_str)

    if op == '=':
        return (ver, ver)
    elif op == '>=':
        return (ver, Version(999999, 999999, 999999))
    elif op == '<=':
        return (Version(0, 0, 0), ver)
    elif op == '>':
        # >1.2.3 means >=1.2.4 (if patch is 0, then >=1.3.0, etc.)
        # We need to find the next version after ver
        next_ver = _next_version(ver)
        return (next_ver, Version(999999, 999999))
    elif op == '<':
        # <1.2.3 means <1.2.3, which is <=1.2.2 (if patch > 0) or <=1.1.999999 (if patch == 0)
        # Actually, <1.2.3 means all versions less than 1.2.3
        # The max version is the one just before 1.2.3
        prev_ver = _prev_version(ver)
        return (Version(0, 0, 0), prev_ver)
    else:
        raise ValueError(f"Invalid operator: {op}")


def _next_version(ver: Version) -> Version:
    """Return the next version after ver."""
    if ver.patch > 0:
        return Version(ver.major, ver.minor, ver.patch - 1)
    elif ver.minor > 0:
        return Version(ver.major, ver.minor - 1, 999999)
    elif ver.major > 0:
        return Version(ver.major - 1, 999999, 999999)
    else:
        # 0.0.0 has no previous version
        raise ValueError("Cannot get next version of 0.0.0")


def _prev_version(ver: Version) -> Version:
    """Return the previous version before ver."""
    if ver.patch > 0:
        return Version(ver.major, ver.minor, ver.patch - 1)
    elif ver.minor > 0:
        return Version(ver.major, ver.minor - 1, 999999)
    elif ver.major > 0:
        return Version(ver.major - 1, 999999, 999999)
    else:
        # 0.0.0 has no previous version
        raise ValueError("Cannot get previous version of 0.0.0")


def _is_prerelease(version: Version) -> bool:
    """Check if a version has a prerelease."""
    return len(version.prerelease) > 0


def _has_same_major_minor_patch(v1: Version, v2: Version) -> bool:
    """Check if two versions have the same major.minor.patch."""
    return v1.major == v2.major and v1.minor == v2.minor and v1.patch == v2.patch


def _version_satisfies_comparator_set(version: Version, comparators: List[Tuple[str, Version]]) -> bool:
    """
    Check if a version satisfies a set of comparators.
    Each comparator is (op, version).
    """
    # Check if any comparator in the set has a prerelease with the same major.minor.patch
    # If so, the version must also have a prerelease with the same major.minor.patch
    has_prerelease_comparator = False
    for op, comp_ver in comparators:
        if _is_prerelease(comp_ver) and _has_same_major_minor_patch(version, comp_ver):
            has_prerelease_comparator = True
            break

    if has_prerelease_comparator and not _is_prerelease(version):
        return False

    # Check all comparators
    for op, comp_ver in comparators:
        if op == '>=':
            if not (version >= comp_ver):
                return False
        elif op == '<=':
            if not (version <= comp_ver):
                return False
        elif op == '>':
            if not (version > comp_ver):
                return False
        elif op == '<':
            if not (version < comp_ver):
                return False
        elif op == '=':
            if not (version == comp_ver):
                return False

    return True


def _parse_range(rng: str) -> List[List[Tuple[str, Version]]]:
    """
    Parse a range string into a list of comparator sets.
    Each comparator set is a list of (op, version) tuples.
    """
    rng = rng.strip()
    if not rng:
        raise ValueError("Empty range")

    # Split by ||
    sets = rng.split('||')
    result = []

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            raise ValueError("Empty comparator set")

        if set_str == '*':
            # Matches any release
            result.append([])
            continue

        # Split by whitespace to get comparators
        comparators = set_str.split()
        if not comparators:
            raise ValueError("Empty comparator set")

        comparator_set = []
        for comp in comparators:
            comp = comp.strip()
            if not comp:
                continue

            # Check for tilde, caret, hyphen
            if comp.startswith('~'):
                # Tilde range
                ver_str = comp[1:].strip()
                if not ver_str:
                    raise ValueError(f"Invalid tilde range: {comp}")
                ver = _parse_partial_version(ver_str)
                # ~1.2.3 is >=1.2.3 <1.3.0
                # ~1.2 is >=1.2.0 <1.3.0
                # ~1 is >=1.0.0 <2.0.0
                if ver.patch > 0 or (ver.minor > 0 and ver.patch == 0) or (ver.major > 0 and ver.minor == 0 and ver.patch == 0):
                    # Determine the upper bound
                    if ver.patch > 0:
                        # ~1.2.3 -> >=1.2.3 <1.3.0
                        upper = Version(ver.major, ver.minor + 1, 0)
                    elif ver.minor > 0:
                        # ~1.2 -> >=1.2.0 <1.3.0
                        upper = Version(ver.major, ver.minor + 1, 0)
                    else:
                        # ~1 -> >=1.0.0 <2.0.0
                        upper = Version(ver.major + 1, 0, 0)
                    comparator_set.append(('>=', ver))
                    comparator_set.append(('<', upper))
                else:
                    raise ValueError(f"Invalid tilde range: {comp}")
            elif comp.startswith('^'):
                # Caret range
                ver_str = comp[1:].strip()
                if not ver_str:
                    raise ValueError(f"Invalid caret range: {comp}")
                ver = _parse_partial_version(ver_str)
                # ^1.2.3 is >=1.2.3 <2.0.0
                # ^0.2.3 is >=0.2.3 <0.3.0
                # ^0.0.3 is >=0.0.3 <0.0.4
                if ver.major > 0:
                    upper = Version(ver.major + 1, 0, 0)
                elif ver.minor > 0:
                    upper = Version(0, ver.minor + 1, 0)
                else:
                    upper = Version(0, 0, ver.patch + 1)
                comparator_set.append(('>=', ver))
                comparator_set.append(('<', upper))
            elif '-' in comp:
                # Hyphen range: 1.2.3 - 2.3.4
                parts = comp.split('-')
                if len(parts) != 2:
                    raise ValueError(f"Invalid hyphen range: {comp}")
                lower_str = parts[0].strip()
                upper_str = parts[1].strip()
                if not lower_str or not upper_str:
                    raise ValueError(f"Invalid hyphen range: {comp}")

                lower_ver = _parse_partial_version(lower_str)
                upper_ver = _parse_partial_version(upper_str)

                # Hyphen range: >=lower <=upper
                # But if upper is partial, it's exclusive of the next
                # e.g., 1.2.3 - 2.3 is >=1.2.3 <2.4.0
                # We need to determine if upper is partial
                # If upper is partial, we need to find the next version after the partial
                # Actually, the spec says: a partial upper bound is exclusive of the next
                # So 1.2.3 - 2.3 means >=1.2.3 <2.4.0
                # Let's parse upper and determine the exclusive upper bound
                if upper_ver.patch == 0 and upper_ver.minor == 0 and upper_ver.major == 0:
                    # 0.0.0 is a special case
                    comparator_set.append(('>=', lower_ver))
                    comparator_set.append(('<=', upper_ver))
                else:
                    # Check if upper is a partial version (i.e., it was parsed from something like 2.3)
                    # We need to check if the original string had partial version
                    # Actually, we can check if the upper version has zeros in minor/patch that were not specified
                    # But we already parsed it, so we need to re-parse to check
                    # Let's use a different approach: check if the upper string contains x, X, *
                    if re.search(r'[xX*]', upper_str):
                        # Partial upper bound
                        # Find the next version after the partial
                        # e.g., 2.3 -> next is 2.4.0
                        # 2 -> next is 3.0.0
                        # We need to determine the next version based on the partial
                        # If upper_str is '2.3', then next is 2.4.0
                        # If upper_str is '2', then next is 3.0.0
                        # Let's parse the upper string again to determine the partial
                        upper_parts = upper_str.strip().split('.')
                        if len(upper_parts) == 1:
                            # e.g., 2 -> next is 3.0.0
                            next_upper = Version(int(upper_parts[0].replace('x', '0').replace('X', '0').replace('*', '0')) + 1, 0, 0)
                        elif len(upper_parts) == 2:
                            # e.g., 2.3 -> next is 2.4.0
                            next_upper = Version(int(upper_parts[0].replace('x', '0').replace('X', '0').replace('*', '0')), int(upper_parts[1].replace('x', '0').replace('X', '0').replace('*', '0')) + 1, 0)
                        else:
                            # e.g., 2.3.4 -> next is 2.3.5
                            next_upper = Version(int(upper_parts[0].replace('x', '0').replace('X', '0').replace('*', '0')), int(upper_parts[1].replace('x', '0').replace('X', '0').replace('*', '0')), int(upper_parts[2].replace('x', '0').replace('X', '0').replace('*', '0')) + 1)
                        comparator_set.append(('>=', lower_ver))
                        comparator_set.append(('<', next_upper))
                    else:
                        # Full upper bound
                        comparator_set.append(('>=', lower_ver))
                        comparator_set.append(('<=', upper_ver))
            else:
                # Regular comparator
                op = None
                ver_str = comp
                if comp.startswith('>='):
                    op = '>='
                    ver_str = comp[2:].strip()
                elif comp.startswith('<='):
                    op = '<='
                    ver_str = comp[2:].strip()
                elif comp.startswith('>'):
                    op = '>'
                    ver_str = comp[1:].strip()
                elif comp.startswith('<'):
                    op = '<'
                    ver_str = comp[1:].strip()
                elif comp.startswith('='):
                    op = '='
                    ver_str = comp[1:].strip()
                else:
                    op = '='
                    ver_str = comp

                if not ver_str:
                    raise ValueError(f"Invalid comparator: {comp}")

                ver = _parse_partial_version(ver_str)

                if op == '>':
                    # >1.2.3 means >=1.2.4 (if patch is 0, then >=1.3.0, etc.)
                    next_ver = _next_version(ver)
                    comparator_set.append(('>=', next_ver))
                elif op == '<':
                    # <1.2.3 means <1.2.3, which is <=1.2.2 (if patch > 0) or <=1.1.999999 (if patch == 0)
                    prev_ver = _prev_version(ver)
                    comparator_set.append(('<=', prev_ver))
                else:
                    comparator_set.append((op, ver))

        if not comparator_set:
            raise ValueError(f"Empty comparator set in: {set_str}")

        result.append(comparator_set)

    return result


def satisfies(version: str, rng: str) -> bool:
    """
    Check if a version satisfies a range.
    """
    try:
        ver = Version.parse(version)
    except ValueError:
