class Version:
    """Represents a SemVer 2.0.0 version."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[List[str]] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease if prerelease is not None else []
        self.build = build

    @classmethod
    def parse(cls, v: str) -> 'Version':
        """Parse a SemVer string into a Version object."""
        if not isinstance(v, str):
            raise ValueError(f"Invalid version: {v}")

        # Strip leading 'v' or '='
        s = v.strip()
        if s.startswith('v') or s.startswith('V'):
            s = s[1:]
        if s.startswith('='):
            s = s[1:]
        s = s.strip()

        if not s:
            raise ValueError(f"Invalid version: {v}")

        # SemVer regex
        # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        # No leading zeros in numeric parts
        # Prerelease identifiers: [0-9A-Za-z-]+, non-empty
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version: {v}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease_str = match.group(4)
        build_str = match.group(5)

        prerelease = None
        if prerelease_str is not None:
            prerelease = prerelease_str.split('.')

        build = build_str

        return cls(major, minor, patch, prerelease, build)

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(self.prerelease)
        if self.build:
            s += "+" + self.build
        return f"Version({s})"

    def __str__(self):
        return self.__repr__()

    def _cmp_key(self) -> Tuple[int, int, int, Union[Tuple[int, ...], Tuple[str, ...]]]:
        """
        Return a comparison key for SemVer precedence.
        Build metadata is ignored.
        Prerelease < release.
        Prerelease identifiers compared numerically when both numeric, numeric < alphanumeric, ASCII order otherwise.
        A shorter prefix list is smaller.
        """
        # For comparison, we need to handle prerelease specially
        if self.prerelease:
            # Convert prerelease identifiers: numeric strings become integers for proper comparison
            # But we need a key that allows proper ordering
            # Each identifier: if it's all digits, it's numeric; otherwise alphanumeric
            # Numeric identifiers are compared as integers
            # Alphanumeric identifiers are compared as strings
            # Numeric < Alphanumeric
            # We'll create a tuple where each element is (0, int_val) for numeric or (1, str_val) for alphanumeric
            key = []
            for ident in self.prerelease:
                if ident.isdigit():
                    key.append((0, int(ident)))
                else:
                    key.append((1, ident))
            return (self.major, self.minor, self.patch, 0, tuple(key))
        else:
            # Release version has no prerelease, so it's greater than any prerelease of the same major.minor.patch
            return (self.major, self.minor, self.patch, 1, ())

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() == other._cmp_key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() < other._cmp_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() <= other._cmp_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() > other._cmp_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() >= other._cmp_key()

    def __ne__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() != other._cmp_key()

    def __hash__(self):
        return hash(self._cmp_key())


# Alias for backward compatibility
