def _parse_partial_version(s: str) -> Version:
    """
    Parse a partial version string like '1', '1.2', '1.2.3', '1.x', '1.2.*', 'X'.
    Returns a Version object with missing parts filled with 0.
    """
    s = s.strip()
    if not s:
        raise ValueError("Empty version string")

    # Replace x, X, * with 0
    s = re.sub(r'[xX*]', '0', s)

    # Now parse as normal version
