def _next_version(ver: Version) -> Version:
    """Return the next version after ver."""
    if ver.patch > 0:
        return Version(ver.major, ver.minor, ver.patch - 1)
    elif ver.minor > 0:
        return Version(ver.major, ver.minor - 1, 999999)
    elif ver.major > 0:
        return Version(ver.major - 1, 999999, 999999)
    else:
        # 0.0.0 has no previous version
        raise ValueError("Cannot get next version of 0.0.0")


def _prev_version(ver: Version) -> Version:
    """Return the previous version before ver."""
    if ver.patch > 0:
        return Version(ver.major, ver.minor, ver.patch - 1)
    elif ver.minor > 0:
        return Version(ver.major, ver.minor - 1, 999999)
    elif ver.major > 0:
        return Version(ver.major - 1, 999999, 999999)
    else:
        # 0.0.0 has no previous version
        raise ValueError("Cannot get previous version of 0.0.0")


