    """Check if a version has a prerelease."""
    return len(version.prerelease) > 0


def _has_same_major_minor_patch(v1: Version, v2: Version) -> bool:
    """Check if two versions have the same major.minor.patch."""
    return v1.major == v2.major and v1.minor == v2.minor and v1.patch == v2.patch


def _version_satisfies_comparator_set(version: Version, comparators: List[Tuple[str, Version]]) -> bool:
    """
    Check if a version satisfies a set of comparators.
    Each comparator is (op, version).
    """
    # Check if any comparator in the set has a prerelease with the same major.minor.patch
    # If so, the version must also have a prerelease with the same major.minor.patch
    has_prerelease_comparator = False
    for op, comp_ver in comparators:
        if _is_prerelease(comp_ver) and _has_same_major_minor_patch(version, comp_ver):
            has_prerelease_comparator = True
            break

    if has_prerelease_comparator and not _is_prerelease(version):
        return False

    # Check all comparators
    for op, comp_ver in comparators:
        if op == '>=':
            if not (version >= comp_ver):
                return False
        elif op == '<=':
            if not (version <= comp_ver):
                return False
        elif op == '>':
            if not (version > comp_ver):
                return False
        elif op == '<':
            if not (version < comp_ver):
                return False
        elif op == '=':
            if not (version == comp_ver):
                return False

    return True


def _parse_range(rng: str) -> List[List[Tuple[str, Version]]]:
    """
    Parse a range string into a list of comparator sets.
    Each comparator set is a list of (op, version) tuples.
    """
    rng = rng.strip()
    if not rng:
        raise ValueError("Empty range")

    # Split by ||
    sets = rng.split('||')
    result = []

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            raise ValueError("Empty comparator set")

        if set_str == '*':
            # Matches any release
            result.append([])
            continue

        # Split by whitespace to get comparators
        comparators = set_str.split()
        if not comparators:
            raise ValueError("Empty comparator set")

        comparator_set = []
        for comp in comparators:
            comp = comp.strip()
            if not comp:
                continue

            # Check for tilde, caret, hyphen
            if comp.startswith('~'):
                # Tilde range
                ver_str = comp[1:].strip()
                if not ver_str:
                    raise ValueError(f"Invalid tilde range: {comp}")
                ver = _parse_partial_version(ver_str)
                # ~1.2.3 is >=1.2.3 <1.3.0
                # ~1.2 is >=1.2.0 <1.3.0
                # ~1 is >=1.0.0 <2.0.0
                if ver.patch > 0 or (ver.minor > 0 and ver.patch == 0) or (ver.major > 0 and ver.minor == 0 and ver.patch == 0):
                    # Determine the upper bound
                    if ver.patch > 0:
                        # ~1.2.3 -> >=1.2.3 <1.3.0
                        upper = Version(ver.major, ver.minor + 1, 0)
                    elif ver.minor > 0:
                        # ~1.2 -> >=1.2.0 <1.3.0
                        upper = Version(ver.major, ver.minor + 1, 0)
                    else:
                        # ~1 -> >=1.0.0 <2.0.0
                        upper = Version(ver.major + 1, 0, 0)
                    comparator_set.append(('>=', ver))
                    comparator_set.append(('<', upper))
                else:
                    raise ValueError(f"Invalid tilde range: {comp}")
            elif comp.startswith('^'):
                # Caret range
                ver_str = comp[1:].strip()
                if not ver_str:
                    raise ValueError(f"Invalid caret range: {comp}")
                ver = _parse_partial_version(ver_str)
                # ^1.2.3 is >=1.2.3 <2.0.0
                # ^0.2.3 is >=0.2.3 <0.3.0
                # ^0.0.3 is >=0.0.3 <0.0.4
                if ver.major > 0:
                    upper = Version(ver.major + 1, 0, 0)
                elif ver.minor > 0:
                    upper = Version(0, ver.minor + 1, 0)
                else:
                    upper = Version(0, 0, ver.patch + 1)
                comparator_set.append(('>=', ver))
                comparator_set.append(('<', upper))
            elif '-' in comp:
