                parts = comp.split('-')
                if len(parts) != 2:
                    raise ValueError(f"Invalid hyphen range: {comp}")
                lower_str = parts[0].strip()
                upper_str = parts[1].strip()
                if not lower_str or not upper_str:
                    raise ValueError(f"Invalid hyphen range: {comp}")

                lower_ver = _parse_partial_version(lower_str)
                upper_ver = _parse_partial_version(upper_str)

                # Hyphen range: >=lower <=upper
                # But if upper is partial, it's exclusive of the next
                # e.g., 1.2.3 - 2.3 is >=1.2.3 <2.4.0
                # We need to determine if upper is partial
                # If upper is partial, we need to find the next version after the partial
                # Actually, the spec says: a partial upper bound is exclusive of the next
                # So 1.2.3 - 2.3 means >=1.2.3 <2.4.0
                # Let's parse upper and determine the exclusive upper bound
                if upper_ver.patch == 0 and upper_ver.minor == 0 and upper_ver.major == 0:
                    # 0.0.0 is a special case
                    comparator_set.append(('>=', lower_ver))
                    comparator_set.append(('<=', upper_ver))
                else:
