                    # We need to check if the original string had partial version
                    # Let's use a different approach: check if the upper string contains x, X, *
                    if re.search(r'[xX*]', upper_str):
                        # Partial upper bound
                        # Find the next version after the partial
                        # e.g., 2.3 -> next is 2.4.0
                        # 2 -> next is 3.0.0
                        # We need to determine the next version based on the partial
                        # If upper_str is '2.3', then next is 2.4.0
                        # If upper_str is '2', then next is 3.0.0
                        # Let's parse the upper string again to determine the partial
                        upper_parts = upper_str.strip().split('.')
                        if len(upper_parts) == 1:
                            # e.g., 2 -> next is 3.0.0
                            next_upper = Version(int(upper_parts[0].replace('x', '0').replace('X', '0').replace('*', '0')) + 1, 0, 0)
                        elif len(upper_parts) == 2:
                            # e.g., 2.3 -> next is 2.4.0
                            next_upper = Version(int(upper_parts[0].replace('x', '0').replace('X', '0').replace('*', '0')), int(upper_parts[1].replace('x', '0').replace('X', '0').replace('*', '0')) + 1, 0)
                        else:
                            # e.g., 2.3.4 -> next is 2.3.5
                            next_upper = Version(int(upper_parts[0].replace('x', '0').replace('X', '0').replace('*', '0')), int(upper_parts[1].replace('x', '0').replace('X', '0').replace('*', '0')), int(upper_parts[2].replace('x', '0').replace('X', '0').replace('*', '0')) + 1)
                        comparator_set.append(('>=', lower_ver))
                        comparator_set.append(('<', next_upper))
                    else:
                        # Full upper bound
                        comparator_set.append(('>=', lower_ver))
                        comparator_set.append(('<=', upper_ver))
            else:
                # Regular comparator
                op = None
                ver_str = comp
                if comp.startswith('>='):
                    op = '>='
                    ver_str = comp[2:].strip()
                elif comp.startswith('<='):
                    op = '<='
                    ver_str = comp[2:].strip()
                elif comp.startswith('>'):
                    op = '>'
                    ver_str = comp[1:].strip()
                elif comp.startswith('<'):
                    op = '<'
                    ver_str = comp[1:].strip()
                elif comp.startswith('='):
                    op = '='
                    ver_str = comp[1:].strip()
                else:
                    op = '='
                    ver_str = comp

                if not ver_str:
                    raise ValueError(f"Invalid comparator: {comp}")

                ver = _parse_partial_version(ver_str)

                if op == '>':
                    # >1.2.3 means >=1.2.4 (if patch is 0, then >=1.3.0, etc.)
                    next_ver = _next_version(ver)
                    comparator_set.append(('>=', next_ver))
                elif op == '<':
                    # <1.2.3 means <1.2.3, which is <=1.2.2 (if patch > 0) or <=1.1.999999 (if patch == 0)
                    prev_ver = _prev_version(ver)
                    comparator_set.append(('<=', prev_ver))
                else:
                    comparator_set.append((op, ver))

        if not comparator_set:
            raise ValueError(f"Empty comparator set in: {set_str}")

        result.append(comparator_set)

    return result


def satisfies(version: str, rng: str) -> bool:
    """
    Check if a version satisfies a range.
    """
    try:
        ver = Version.parse(version)
    except ValueError:
        raise ValueError(f"Invalid version: {version}")

    try:
        comparator_sets = _parse_range(rng)
    except ValueError:
        raise ValueError(f"Invalid range: {rng}")

    # Check if any comparator set matches
    for comp_set in comparator_sets:
        if _version_satisfies_comparator_set(ver, comp_set):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """
