    """
    try:
        comparator_sets = _parse_range(rng)
    except ValueError:
        raise ValueError(f"Invalid range: {rng}")

    # Parse all versions
    parsed_versions = []
    for v_str in versions:
        try:
            ver = Version.parse(v_str)
            parsed_versions.append((v_str, ver))
        except ValueError:
            # Skip invalid versions
