def _resolve_type_hint(annotation: Any, globalns: dict | None = None, localns: dict | None = None) -> Any:
    """Resolve a type annotation, handling string annotations via get_type_hints."""
    # If it's already a resolved type, return it
    if isinstance(annotation, str):
        # This shouldn't happen if we use get_type_hints properly, but just in case
        raise ValueError(f"Unresolved string annotation: {annotation}")
    return annotation


def _is_union_type(tp: Any) -> bool:
    """Check if a type is a Union type (including Optional)."""
    origin = get_origin(tp)
    if origin is Union:
        return True
    if UnionType is not None and isinstance(tp, UnionType):
        return True
    return False


def _get_union_args(tp: Any) -> tuple:
    """Get the arguments of a Union type."""
    origin = get_origin(tp)
    if origin is Union:
        return get_args(tp)
    if UnionType is not None and isinstance(tp, UnionType):
        return get_args(tp)
    return ()


def _is_optional(tp: Any) -> bool:
    """Check if a type is Optional[T] (i.e., Union[T, None])."""
    if not _is_union_type(tp):
        return False
    args = _get_union_args(tp)
    non_none_args = [a for a in args if a is not type(None)]
    return len(non_none_args) == 1 and len(args) == 2


def _get_optional_inner(tp: Any) -> Any:
