    """Get the item type of a list[T]."""
    args = get_args(tp)
    if args:
        return args[0]
    return Any


def _is_dict(tp: Any) -> bool:
    """Check if a type is dict[str, T]."""
    return get_origin(tp) is dict


def _get_dict_key_type(tp: Any) -> Any:
    """Get the key type of a dict[str, T]."""
    args = get_args(tp)
    if len(args) >= 1:
        return args[0]
    return Any


def _get_dict_value_type(tp: Any) -> Any:
