def _load_value(tp: Any, data: Any, path: str, globalns: dict | None = None, localns: dict | None = None) -> Any:
    """Load a value of type tp from data, starting at the given path."""
    # Resolve string annotations if needed
    if isinstance(tp, str):
        if globalns is None and localns is None:
            raise ValueError(f"Cannot resolve string annotation: {tp}")
        tp = eval(tp, globalns or {}, localns or {})

    # Handle None type
    if tp is type(None):
        if data is None:
            return None
        else:
            raise LoadError(path, f"Expected None, got {type(data).__name__}")

    # Handle Literal types
    if _is_literal(tp):
        literal_values = _get_literal_values(tp)
        # Check if data matches one of the literal values
        for lv in literal_values:
            if data == lv and type(data) is type(lv):
                return lv
        # If no match, raise error
        raise LoadError(path, f"Expected one of {literal_values}, got {data!r}")

    # Handle Union types (including Optional)
    if _is_union_type(tp):
        args = _get_union_args(tp)
        # Try each type in order
        errors = []
        for arg_tp in args:
            try:
                return _load_value(arg_tp, data, path, globalns, localns)
            except LoadError as e:
                errors.append(e)
            except Exception as e:
                errors.append(LoadError(path, f"Failed to load as {arg_tp}: {e}"))
        # If we get here, none of the union members worked
        # For Optional, if data is not None, we report the error from the non-None type
        # For general unions, we report the first error or a combined error
        if len(errors) > 0:
            # Report the first error
            raise errors[0]
        raise LoadError(path, f"Could not load as any of {args}")

    # Handle bool type specifically (before int, since bool is a subclass of int)
    if tp is bool:
        if isinstance(data, bool):
            return data
        else:
            raise LoadError(path, f"Expected bool, got {type(data).__name__}")

    # Handle int type
    if tp is int:
        if isinstance(data, int) and not isinstance(data, bool):
            return data
        else:
            raise LoadError(path, f"Expected int, got {type(data).__name__}")

    # Handle float type
    if tp is float:
        if isinstance(data, float):
            return data
        elif isinstance(data, int) and not isinstance(data, bool):
            return float(data)
        else:
            raise LoadError(path, f"Expected float, got {type(data).__name__}")

    # Handle str type
    if tp is str:
        if isinstance(data, str):
            return data
        else:
            raise LoadError(path, f"Expected str, got {type(data).__name__}")

    # Handle list type
    if _is_list(tp):
        if not isinstance(data, list):
            raise LoadError(path, f"Expected list, got {type(data).__name__}")
        item_tp = _get_list_item_type(tp)
        result = []
        for i, item in enumerate(data):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item_tp, item, item_path, globalns, localns))
        return result

    # Handle dict type
    if _is_dict(tp):
        if not isinstance(data, dict):
            raise LoadError(path, f"Expected dict, got {type(data).__name__}")
        key_tp = _get_dict_key_type(tp)
        value_tp = _get_dict_value_type(tp)
        # For dict, keys must be str
        if key_tp is not str and key_tp is not Any:
            # We'll just accept str keys for now as per the spec (dict[str, T])
            pass
        result = {}
        for key, value in data.items():
            if not isinstance(key, str):
                raise LoadError(path, f"Expected dict with str keys, got key of type {type(key).__name__}")
            value_path = f"{path}.{key}"
            result[key] = _load_value(value_tp, value, value_path, globalns, localns)
        return result

    # Handle tuple type
    if _is_tuple(tp):
        if not isinstance(data, list):
            raise LoadError(path, f"Expected tuple (from list), got {type(data).__name__}")
        tuple_args = _get_tuple_args(tp)

        if _is_tuple_variadic(tp):
            # tuple[T, ...]
            if len(tuple_args) == 1 and tuple_args[0] is Ellipsis:
                item_tp = tuple_args[0]
                # Actually, for tuple[T, ...], the item type is the first arg
                # But get_args returns (T, Ellipsis), so we need to handle this
                # Let me re-check: for tuple[int, ...], get_args returns (int, Ellipsis)
                # So we need to get the first arg which is the item type
                item_tp = tuple_args[0]
                result = []
                for i, item in enumerate(data):
                    item_path = f"{path}[{i}]"
                    result.append(_load_value(item_tp, item, item_path, globalns, localns))
                return tuple(result)
            else:
                raise LoadError(path, f"Invalid variadic tuple type: {tp}")
        else:
            # Fixed-length tuple
            if len(data) != len(tuple_args):
                raise LoadError(path, f"Expected tuple of length {len(tuple_args)}, got {len(data)}")
            result = []
            for i, (item_tp, item) in enumerate(zip(tuple_args, data)):
                item_path = f"{path}[{i}]"
                result.append(_load_value(item_tp, item, item_path, globalns, localns))
            return tuple(result)

    # Handle dataclass types
    if _is_dataclass(tp):
        if not isinstance(data, dict):
            raise LoadError(path, f"Expected dict for dataclass {tp.__name__}, got {type(data).__name__}")
        return _load_dataclass(tp, data, path, globalns, localns)

    # Handle Any or unknown types
    if tp is Any:
        return data

    # If we get here, we don't know how to handle this type
    raise LoadError(path, f"Unsupported type: {tp}")


def _load_dataclass(cls: type, data: dict, path: str, globalns: dict | None = None, localns: dict | None = None) -> Any:
    """Load a dataclass instance from a dict."""
    if not dataclasses.is_dataclass(cls):
        raise LoadError(path, f"Not a dataclass: {cls}")

    # Get type hints
    try:
        hints = get_type_hints(cls, globalns, localns)
    except Exception as e:
        raise LoadError(path, f"Failed to get type hints for {cls.__name__}: {e}")

    # Get field info
    fields = dataclasses.fields(cls)
    field_map = {f.name: f for f in fields}

    # Check for unknown keys
    for key in data:
        if key not in field_map:
            raise LoadError(f"{path}.{key}", f"Unknown key: {key}")

    # Build the instance
    kwargs = {}
    for field in fields:
        field_name = field.name
        if field_name in data:
            # Load the value
            tp = hints.get(field_name, Any)
            value_path = f"{path}.{field_name}"
            kwargs[field_name] = _load_value(tp, data[field_name], value_path, globalns, localns)
        else:
            # Check for default
            if field.default is not dataclasses.MISSING:
                kwargs[field_name] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                kwargs[field_name] = field.default_factory()
            else:
                raise LoadError(f"{path}.{field_name}", f"Missing required field: {field_name}")

    return cls(**kwargs)


def load(cls: type, data: Any) -> Any:
    """Load an instance of a dataclass from JSON-like data."""
    if not dataclasses.is_dataclass(cls):
        raise LoadError("$", f"Not a dataclass: {cls}")

    try:
        hints = get_type_hints(cls)
    except Exception as e:
        raise LoadError("$", f"Failed to get type hints for {cls.__name__}: {e}")

    return _load_dataclass(cls, data, "$")
