    row_idx = 0
    current_field_count = 0
    pos = 1
    in_quote = 0
    current_field = ""

    # We will store fields in a flat array
    # To handle variable number of fields, we just append

    while (pos <= len) {
        ch = substr(input, pos, 1)

        if (in_quote) {
            if (ch == "\"") {
                if (pos + 1 <= len && substr(input, pos + 1, 1) == "\"") {
                    current_field = current_field "\""
                    pos = pos + 2
                } else {
                    in_quote = 0
                    pos = pos + 1
                }
            } else {
                current_field = current_field ch
                pos = pos + 1
            }
        } else {
            if (ch == "\"") {
                in_quote = 1
                pos = pos + 1
            } else if (ch == delim) {
                current_field_count++
                rows[row_idx, current_field_count] = current_field
                current_field = ""
                pos = pos + 1
            } else if (ch == "\r") {
                if (pos + 1 <= len && substr(input, pos + 1, 1) == "\n") {
                    pos = pos + 2
                } else {
                    pos = pos + 1
                }
                current_field_count++
                rows[row_idx, current_field_count] = current_field
                row_lengths[row_idx] = current_field_count
                current_field_count = 0
                current_field = ""
                row_idx++
            } else if (ch == "\n") {
                current_field_count++
                rows[row_idx, current_field_count] = current_field
                row_lengths[row_idx] = current_field_count
                current_field_count = 0
                current_field = ""
                row_idx++
                pos = pos + 1
            } else {
                current_field = current_field ch
                pos = pos + 1
            }
        }
    }

    # Check for unterminated quote
    if (in_quote) {
        print "Error: Unterminated quote at end of input" > "/dev/stderr"
        exit 4
    }

    # Handle last field if row was not terminated by newline
    if (current_field_count > 0 || (pos > len && current_field != "")) {
        current_field_count++
        rows[row_idx, current_field_count] = current_field
        row_lengths[row_idx] = current_field_count
        row_idx++
    } else if (pos > len && current_field == "" && current_field_count == 0) {
        # Empty file or just whitespace? 
        # If we have no rows, error
        if (row_idx == 0) {
            print "Error: No header row found" > "/dev/stderr"
            exit 3
        }
    }

    total_rows = row_idx

    if (total_rows == 0) {
        print "Error: No header row found" > "/dev/stderr"
        exit 3
    }

    header_count = row_lengths[0]

    # Determine column index
    col_idx = -1
    if (column_spec ~ /^#[0-9]+$/) {
        n = substr(column_spec, 2) + 0
        if (n < 1 || n > header_count) {
            print "Error: Unknown column: " column_spec > "/dev/stderr"
            exit 3
        }
        col_idx = n
    } else {
        for (i = 1; i <= header_count; i++) {
            if (rows[0, i] == column_spec) {
                col_idx = i
                break
            }
        }
        if (col_idx == -1) {
            print "Error: Unknown column: " column_spec > "/dev/stderr"
            exit 3
        }
    }

    # Extract column values
    if (sum_mode) {
        count = 0
        sum = 0
        min = ""
        max = ""

        for (r = 1; r < total_rows; r++) {
            if (r in row_lengths && col_idx <= row_lengths[r]) {
                val = rows[r, col_idx]
            } else {
                val = ""
            }

            # Check if numeric
            if (val ~ /^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)$/) {
                num = val + 0
                count++
                sum += num
                if (min == "" || num < min) {
                    min = num
                }
                if (max == "" || num > max) {
                    max = num
                }
            }
        }

        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, min, max
        }
    } else {
        for (r = 1; r < total_rows; r++) {
            if (r in row_lengths && col_idx <= row_lengths[r]) {
                val = rows[r, col_idx]
            } else {
                val = ""
            }

            # Replace embedded newlines with literal \n
            gsub(/\n/, "\\n", val)
            print val
        }
    }
}
' < <(eval "$INPUT_CMD")
