#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 1 ]]; then
    echo "Usage: solution.sh FILE" >&2
    exit 1
fi

FILE="$1"

if [[ ! -f "$FILE" ]]; then
    echo "Error: File '$FILE' not found" >&2
    exit 1
fi

# We'll use awk to parse the file and output the result.
# Since we need to handle the "later value wins but keeps its later position" rule,
# we need to track the order of keys and their values.

awk '
BEGIN {
    key_count = 0
}

{
    lineno = NR
    line = $0

    # Skip blank lines
    if (line ~ /^[[:space:]]*$/) {
        next
    }

    # Skip comment lines (first non-blank char is #)
    if (line ~ /^[[:space:]]*#/) {
        next
    }

    # Remove leading whitespace for processing
    stripped = line
    gsub(/^[[:space:]]+/, "", stripped)

    # Check if line starts with "export "
    starts_with_export = 0
    if (substr(stripped, 1, 7) == "export ") {
        starts_with_export = 1
        stripped = substr(stripped, 8)
    }

    # Now stripped should be KEY=VALUE
    # Find the first = sign
    eq_pos = index(stripped, "=")
    if (eq_pos == 0) {
        printf "%s:%d: invalid line\n", FILENAME, lineno > "/dev/stderr"
        exit 1
    }

    key = substr(stripped, 1, eq_pos - 1)
    value_part = substr(stripped, eq_pos + 1)

    # Validate key: must match [A-Za-z_][A-Za-z0-9_]*
    if (key == "" || key !~ /^[A-Za-z_][A-Za-z0-9_]*$/) {
        printf "%s:%d: invalid line\n", FILENAME, lineno > "/dev/stderr"
        exit 1
    }

    # Parse value
    value = ""
    if (value_part == "") {
        # Empty value
        value = ""
    } else if (substr(value_part, 1, 1) == "\"") {
        # Double-quoted value
        # Find the closing double quote
        rest = substr(value_part, 2)
        value = ""
        i = 1
        len = length(rest)
        while (i <= len) {
            c = substr(rest, i, 1)
            if (c == "\\") {
                if (i < len) {
                    nc = substr(rest, i + 1, 1)
                    if (nc == "n") {
                        value = value "\n"
                        i += 2
                    } else if (nc == "\"") {
                        value = value "\""
                        i += 2
                    } else if (nc == "\\") {
                        value = value "\\"
                        i += 2
                    } else {
                        # Other escapes stay as is: backslash followed by the char
                        value = value "\\" nc
                        i += 2
                    }
                } else {
                    # Backslash at end of string - keep it as is? The spec says "other escapes stay as is"
                    # But this is a trailing backslash with nothing after. Let us keep the backslash.
                    value = value "\\"
                    i += 1
                }
            } else if (c == "\"") {
                # Closing quote
                # Everything after must be empty or a comment
                after = substr(rest, i + 1)
                # Trim leading whitespace
                gsub(/^[[:space:]]+/, "", after)
                if (after != "" && substr(after, 1, 1) != "#") {
                    printf "%s:%d: invalid line\n", FILENAME, lineno > "/dev/stderr"
                    exit 1
                }
                break
            } else {
                value = value c
                i += 1
            }
        }
        if (i > len) {
            # Did not find closing quote
            printf "%s:%d: invalid line\n", FILENAME, lineno > "/dev/stderr"
            exit 1
        }
    } else if (substr(value_part, 1, 1) == "'") {
        # Single-quoted value
        rest = substr(value_part, 2)
        # Find the closing single quote
        close_pos = index(rest, "'")
        if (close_pos == 0) {
            printf "%s:%d: invalid line\n", FILENAME, lineno > "/dev/stderr"
            exit 1
        }
        value = substr(rest, 1, close_pos - 1)
        after = substr(rest, close_pos + 1)
        # Trim leading whitespace
        gsub(/^[[:space:]]+/, "", after)
        if (after != "" && substr(after, 1, 1) != "#") {
            printf "%s:%d: invalid line\n", FILENAME, lineno > "/dev/stderr"
            exit 1
        }
    } else {
        # Unquoted value
        # Taken literally up to an unquoted " #" (space then hash)
        # Trailing spaces and tabs are trimmed.
        # "a#b" keeps the hash (no space before #)

        # We need to find " #" that is not inside quotes (but there are no quotes here)
        # So we look for the first occurrence of " #"
        value = ""
        len = length(value_part)
        found_comment = 0
        for (i = 1; i <= len; i++) {
            c = substr(value_part, i, 1)
            if (c == " " && i < len && substr(value_part, i + 1, 1) == "#") {
                # Found comment start
                found_comment = 1
                break
            }
            value = value c
        }

        if (!found_comment) {
            value = value_part
        }

        # Trim trailing spaces and tabs
        gsub(/[[:space:]]+$/, "", value)
    }

    # Track key order and values
    # If key already seen, remove it from the order list and add to end
    if (key in key_index) {
        idx = key_index[key]
        # Remove from order list
        new_order = ""
        for (j = 1; j <= key_count; j++) {
            if (j != idx) {
                if (new_order == "") {
                    new_order = order[j]
                } else {
                    new_order = new_order SUBSEP order[j]
                }
            }
        }
        order = new_order SUBSEP key
        key_count--
        delete key_index[key]
    }

    key_count++
    key_index[key] = key_count
    order = order SUBSEP key
    values[key] = value
}

END {
    # Print in order
    if (key_count > 0) {
        n = split(order, keys, SUBSEP)
        for (i = 1; i <= n; i++) {
            k = keys[i]
            if (k == "") continue
            v = values[k]
            # Escape single quotes in value: replace ' with '\''
            gsub(/'\''/, "'\\'''\''", v)
            printf "export '\''%s'\''='\''%s'\''\n", k, v
        }
    }
}
' FILENAME="$FILE" "$FILE"
